insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Electric potential: Electrostatics', 'An electric potential at a point r in a static electric field E is given by the line integral where C is an arbitrary path from some fixed reference point to r; it is uniquely determined up to a constant that is added or subtracted from the integral. In electrostatics, the Maxwell-Faraday equation reveals that the curl is zero, making the electric field conservative. Thus, the line integral above does not depend on the specific path C chosen but only on its endpoints, making This states that the electric field points "downhill" towards lower voltages. By Gauss''s law, the potential can also be found to satisfy Poisson''s equation: The concept of electric potential is closely linked with potential energy. A test charge, q, has an electric potential energy, UE, given by The potential energy and hence, also the electric potential, is only defined up to an additive constant: one must arbitrarily choose a position where the potential energy and the electric potential are zero. , i.e., in the case of a non-conservative electric field (caused by a changing magnetic field; see Maxwell''s equations). The generalization of electric potential to this case is described in the section § Generalization to electrodynamics.', 'Wikipedia: Electric potential', 'https://en.wikipedia.org/w/index.php?title=Electric_potential&oldid=1381508888', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'An electric potential at a point r in a static electric field E is given by the line integral where C is an arbitrary path from some fixed reference point to r; it is uniquely determined up to a constant that is added or subtracted from the integral. In electrostatics, the Maxwell-Faraday equation reveals that the curl is zero, making the electric field conservative. Thus, the line integral above does not depend on the specific path C chosen but only on its endpoints, making This states that the electric field points "downhill" towards lower voltages. By Gauss''s law, the potential can also be found to satisfy Poisson''s equation: The concept of electric potential is closely linked with potential energy. A test charge, q, has an electric potential energy, UE, given by The potential energy and hence, also the electric potential, is only defined up to an additive constant: one must arbitrarily choose a position where the potential energy and the electric potential are zero. , i.e., in the case of a non-conservative electric field (caused by a changing magnetic field; see Maxwell''s equations). The generalization of electric potential to this case is described in the section § Generalization to electrodynamics.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Electric potential: Electric potential due to a point charge', 'The electric potential arising from a point charge, Q, at a distance, r, from the location of Q is observed to be where ε0 is the permittivity of vacuum, VE is known as the Coulomb potential. Note that, in contrast to the magnitude of an electric field due to a point charge, the electric potential scales respective to the reciprocal of the radius, rather than the radius squared. The electric potential at any location, r, in a system of point charges is equal to the sum of the individual electric potentials due to every point charge in the system. This fact simplifies calculations significantly, because addition of potential (scalar) fields is much easier than addition of the electric (vector) fields. Specifically, the potential of a set of discrete point charges qi at points ri becomes ri is a point at which there is a nonzero charge; and R is a region containing all the points at which the charge density is nonzero; The equations given above for the electric potential (and all the equations used here) are in the forms required by SI units. In some other (less common) systems of units, such as CGS-Gaussian, many of these equations would be altered.', 'Wikipedia: Electric potential', 'https://en.wikipedia.org/w/index.php?title=Electric_potential&oldid=1381508888', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'The electric potential arising from a point charge, Q, at a distance, r, from the location of Q is observed to be where ε0 is the permittivity of vacuum, VE is known as the Coulomb potential. Note that, in contrast to the magnitude of an electric field due to a point charge, the electric potential scales respective to the reciprocal of the radius, rather than the radius squared. The electric potential at any location, r, in a system of point charges is equal to the sum of the individual electric potentials due to every point charge in the system. This fact simplifies calculations significantly, because addition of potential (scalar) fields is much easier than addition of the electric (vector) fields. Specifically, the potential of a set of discrete point charges qi at points ri becomes ri is a point at which there is a nonzero charge; and R is a region containing all the points at which the charge density is nonzero; The equations given above for the electric potential (and all the equations used here) are in the forms required by SI units. In some other (less common) systems of units, such as CGS-Gaussian, many of these equations would be altered.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Electric potential: Generalization to electrodynamics', 'When time-varying magnetic fields are present (which is true whenever there are time-varying electric fields and vice versa), it is not possible to describe the electric field simply as a scalar potential V because the electric field is no longer conservative: Instead, one can still define a scalar potential by also including the magnetic vector potential A. In particular, A is defined to satisfy: where B is the magnetic field. By the fundamental theorem of vector calculus, such an A can always be found, since the divergence of the magnetic field is always zero due to the absence of magnetic monopoles. Now, the quantity where V is the scalar potential defined by the conservative field F. The electrostatic potential is simply the special case of this definition where A is time-invariant. On the other hand, for time-varying fields,', 'Wikipedia: Electric potential', 'https://en.wikipedia.org/w/index.php?title=Electric_potential&oldid=1381508888', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'When time-varying magnetic fields are present (which is true whenever there are time-varying electric fields and vice versa), it is not possible to describe the electric field simply as a scalar potential V because the electric field is no longer conservative: Instead, one can still define a scalar potential by also including the magnetic vector potential A. In particular, A is defined to satisfy: where B is the magnetic field. By the fundamental theorem of vector calculus, such an A can always be found, since the divergence of the magnetic field is always zero due to the absence of magnetic monopoles. Now, the quantity where V is the scalar potential defined by the conservative field F. The electrostatic potential is simply the special case of this definition where A is time-invariant. On the other hand, for time-varying fields,');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Ohm''s law', 'Ohm''s law states that in a well-behaved conductor (a so-called ohmic conductor), the electric current between two points is directly proportional to the voltage (the difference of electric potential) across the two points. Introducing the constant of proportionality, the resistance, one arrives at the following mathematical equation used to describe this relationship: or, equivalently, at the same equation expressed in terms of the reciprocal constant of proportionality, the electrical conductance, where I is the current through the conductor, V is the voltage measured across the conductor, R is the resistance of the conductor, and G=1/R is the conductance of the conductor. More specifically, Ohm''s law states that the R (or, equivalently, G) in this relation is constant, independent of the current. If the resistance is not constant, the previous equation cannot be called Ohm''s law, but it can still be used as a definition of static/DC resistance. Ohm''s law is an empirical relation which accurately describes the conductivity of the vast majority of electrically conductive materials over many orders of magnitude of current. However some materials do not obey Ohm''s law; these are called non-ohmic.', 'Wikipedia: Ohm''s law', 'https://en.wikipedia.org/w/index.php?title=Ohm''s_law&oldid=1366731572', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'Ohm''s law states that in a well-behaved conductor (a so-called ohmic conductor), the electric current between two points is directly proportional to the voltage (the difference of electric potential) across the two points. Introducing the constant of proportionality, the resistance, one arrives at the following mathematical equation used to describe this relationship: or, equivalently, at the same equation expressed in terms of the reciprocal constant of proportionality, the electrical conductance, where I is the current through the conductor, V is the voltage measured across the conductor, R is the resistance of the conductor, and G=1/R is the conductance of the conductor. More specifically, Ohm''s law states that the R (or, equivalently, G) in this relation is constant, independent of the current. If the resistance is not constant, the previous equation cannot be called Ohm''s law, but it can still be used as a definition of static/DC resistance. Ohm''s law is an empirical relation which accurately describes the conductivity of the vast majority of electrically conductive materials over many orders of magnitude of current. However some materials do not obey Ohm''s law; these are called non-ohmic.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Ohm''s law', 'The law was named after the German physicist Georg Ohm, who, in a treatise published in 1827, described measurements of applied voltage and current through simple electrical circuits containing various lengths of wire. Ohm explained his experimental results by a slightly more complex equation than the modern form above (see History below). In physics, the term Ohm''s law is also used to refer to various generalizations of the law; for example the vector form of the law used in electromagnetics and material science: where J is the current density at a given location in a resistive material, E is the electric field at that location, and σ (sigma) is a material-dependent parameter called the conductivity, defined as the inverse of resistivity ρ (rho). This reformulation of Ohm''s law is due to Gustav Kirchhoff.', 'Wikipedia: Ohm''s law', 'https://en.wikipedia.org/w/index.php?title=Ohm''s_law&oldid=1366731572', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'The law was named after the German physicist Georg Ohm, who, in a treatise published in 1827, described measurements of applied voltage and current through simple electrical circuits containing various lengths of wire. Ohm explained his experimental results by a slightly more complex equation than the modern form above (see History below). In physics, the term Ohm''s law is also used to refer to various generalizations of the law; for example the vector form of the law used in electromagnetics and material science: where J is the current density at a given location in a resistive material, E is the electric field at that location, and σ (sigma) is a material-dependent parameter called the conductivity, defined as the inverse of resistivity ρ (rho). This reformulation of Ohm''s law is due to Gustav Kirchhoff.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Ohm''s law: Scope', 'Ohm''s law is an empirical law, a generalization from many experiments that have shown that current is approximately proportional to electric field for most materials. It is less fundamental than Maxwell''s equations and is not always obeyed. Any given material will break down under a strong-enough electric field, and some materials of interest in electrical engineering are "non-ohmic" under weak fields. Ohm''s law has been observed on a wide range of length scales. In the early 20th century, it was thought that Ohm''s law would fail at the atomic scale, but experiments have not borne out this expectation. As of 2012, researchers have demonstrated that Ohm''s law works for silicon wires as small as four atoms wide and one atom high.', 'Wikipedia: Ohm''s law', 'https://en.wikipedia.org/w/index.php?title=Ohm''s_law&oldid=1366731572', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'Ohm''s law is an empirical law, a generalization from many experiments that have shown that current is approximately proportional to electric field for most materials. It is less fundamental than Maxwell''s equations and is not always obeyed. Any given material will break down under a strong-enough electric field, and some materials of interest in electrical engineering are "non-ohmic" under weak fields. Ohm''s law has been observed on a wide range of length scales. In the early 20th century, it was thought that Ohm''s law would fail at the atomic scale, but experiments have not borne out this expectation. As of 2012, researchers have demonstrated that Ohm''s law works for silicon wires as small as four atoms wide and one atom high.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Ohm''s law: Microscopic origins', 'The dependence of the current density on the applied electric field is essentially quantum mechanical in nature; (see Classical and quantum conductivity.) A qualitative description leading to Ohm''s law can be based upon classical mechanics using the Drude model developed by Paul Drude in 1900. The Drude model treats electrons (or other charge carriers) like pinballs bouncing among the ions that make up the structure of the material. Electrons will be accelerated in the opposite direction to the electric field by the average electric field at their location. With each collision, though, the electron is deflected in a random direction with a velocity that is much larger than the velocity gained by the electric field. The net result is that electrons take a zigzag path due to the collisions, but generally drift in a direction opposing the electric field. The drift velocity then determines the electric current density and its relationship to E and is independent of the collisions. Drude calculated the average drift velocity from p = −eEτ where p is the average momentum, −e is the charge of the electron and τ is the average time between the collisions. Since both the momentum and the current density are proportional to the drift velocity, the current density becomes proportional to the applied electric field; this leads to Ohm''s law.', 'Wikipedia: Ohm''s law', 'https://en.wikipedia.org/w/index.php?title=Ohm''s_law&oldid=1366731572', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'The dependence of the current density on the applied electric field is essentially quantum mechanical in nature; (see Classical and quantum conductivity.) A qualitative description leading to Ohm''s law can be based upon classical mechanics using the Drude model developed by Paul Drude in 1900. The Drude model treats electrons (or other charge carriers) like pinballs bouncing among the ions that make up the structure of the material. Electrons will be accelerated in the opposite direction to the electric field by the average electric field at their location. With each collision, though, the electron is deflected in a random direction with a velocity that is much larger than the velocity gained by the electric field. The net result is that electrons take a zigzag path due to the collisions, but generally drift in a direction opposing the electric field. The drift velocity then determines the electric current density and its relationship to E and is independent of the collisions. Drude calculated the average drift velocity from p = −eEτ where p is the average momentum, −e is the charge of the electron and τ is the average time between the collisions. Since both the momentum and the current density are proportional to the drift velocity, the current density becomes proportional to the applied electric field; this leads to Ohm''s law.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Ohm''s law: Hydraulic analogy', 'A hydraulic analogy is sometimes used to describe Ohm''s law. Water pressure, measured by pascals (or PSI), is the analog of voltage because establishing a water pressure difference between two points along a (horizontal) pipe causes water to flow. The water volume flow rate, as in liters per second, is the analog of current, as in coulombs per second. Finally, flow restrictors—such as apertures placed in pipes between points where the water pressure is measured—are the analog of resistors. We say that the rate of water flow through an aperture restrictor is proportional to the difference in water pressure across the restrictor. Similarly, the rate of flow of electrical charge, that is, the electric current, through an electrical resistor is proportional to the difference in voltage measured across the resistor. More generally, the hydraulic head may be taken as the analog of voltage, and Ohm''s law is then analogous to Darcy''s law which relates hydraulic head to the volume flow rate via the hydraulic conductivity.', 'Wikipedia: Ohm''s law', 'https://en.wikipedia.org/w/index.php?title=Ohm''s_law&oldid=1366731572', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'A hydraulic analogy is sometimes used to describe Ohm''s law. Water pressure, measured by pascals (or PSI), is the analog of voltage because establishing a water pressure difference between two points along a (horizontal) pipe causes water to flow. The water volume flow rate, as in liters per second, is the analog of current, as in coulombs per second. Finally, flow restrictors—such as apertures placed in pipes between points where the water pressure is measured—are the analog of resistors. We say that the rate of water flow through an aperture restrictor is proportional to the difference in water pressure across the restrictor. Similarly, the rate of flow of electrical charge, that is, the electric current, through an electrical resistor is proportional to the difference in voltage measured across the resistor. More generally, the hydraulic head may be taken as the analog of voltage, and Ohm''s law is then analogous to Darcy''s law which relates hydraulic head to the volume flow rate via the hydraulic conductivity.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Ohm''s law: Hydraulic analogy', 'Flow and pressure variables can be calculated in fluid flow network with the use of the hydraulic ohm analogy. The method can be applied to both steady and transient flow situations. In the linear laminar flow region, Poiseuille''s law describes the hydraulic resistance of a pipe, but in the turbulent flow region the pressure–flow relations become nonlinear. The hydraulic analogy to Ohm''s law has been used, for example, to approximate blood flow through the circulatory system.', 'Wikipedia: Ohm''s law', 'https://en.wikipedia.org/w/index.php?title=Ohm''s_law&oldid=1366731572', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'Flow and pressure variables can be calculated in fluid flow network with the use of the hydraulic ohm analogy. The method can be applied to both steady and transient flow situations. In the linear laminar flow region, Poiseuille''s law describes the hydraulic resistance of a pipe, but in the turbulent flow region the pressure–flow relations become nonlinear. The hydraulic analogy to Ohm''s law has been used, for example, to approximate blood flow through the circulatory system.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Ohm''s law: Circuit analysis', 'In circuit analysis, three equivalent expressions of Ohm''s law are used interchangeably: Each equation is quoted by some sources as the defining relationship of Ohm''s law, or even just the two that do not correspond to Ohm''s original statement may sometimes be given. The interchangeability of the equation may be represented by a triangle, where V (voltage) is placed on the top section, the I (current) is placed to the left section, and the R (resistance) is placed to the right. The divider between the top and bottom sections indicates division (hence the division bar).', 'Wikipedia: Ohm''s law', 'https://en.wikipedia.org/w/index.php?title=Ohm''s_law&oldid=1366731572', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'In circuit analysis, three equivalent expressions of Ohm''s law are used interchangeably: Each equation is quoted by some sources as the defining relationship of Ohm''s law, or even just the two that do not correspond to Ohm''s original statement may sometimes be given. The interchangeability of the equation may be represented by a triangle, where V (voltage) is placed on the top section, the I (current) is placed to the left section, and the R (resistance) is placed to the right. The divider between the top and bottom sections indicates division (hence the division bar).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Ohm''s law: Resistive circuits', 'Resistors are circuit elements that impede the passage of electric charge in agreement with Ohm''s law, and are designed to have a specific resistance value R. In schematic diagrams, a resistor is shown as a long rectangle or zig-zag symbol. An element (resistor or conductor) that behaves according to Ohm''s law over some operating range is referred to as an ohmic device (or an ohmic resistor) because Ohm''s law and a single value for the resistance suffice to describe the behavior of the device over that range. Ohm''s law holds for circuits containing only resistive elements (no capacitances or inductances) for all forms of driving voltage or current, regardless of whether the driving voltage or current is constant (DC) or time-varying such as AC. At any instant of time Ohm''s law is valid for such circuits. Resistors which are in series or in parallel may be grouped together into a single "equivalent resistance" in order to apply Ohm''s law in analyzing the circuit.', 'Wikipedia: Ohm''s law', 'https://en.wikipedia.org/w/index.php?title=Ohm''s_law&oldid=1366731572', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'Resistors are circuit elements that impede the passage of electric charge in agreement with Ohm''s law, and are designed to have a specific resistance value R. In schematic diagrams, a resistor is shown as a long rectangle or zig-zag symbol. An element (resistor or conductor) that behaves according to Ohm''s law over some operating range is referred to as an ohmic device (or an ohmic resistor) because Ohm''s law and a single value for the resistance suffice to describe the behavior of the device over that range. Ohm''s law holds for circuits containing only resistive elements (no capacitances or inductances) for all forms of driving voltage or current, regardless of whether the driving voltage or current is constant (DC) or time-varying such as AC. At any instant of time Ohm''s law is valid for such circuits. Resistors which are in series or in parallel may be grouped together into a single "equivalent resistance" in order to apply Ohm''s law in analyzing the circuit.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Series and parallel circuits', 'Two-terminal components and electrical networks can be connected in series or parallel. The resulting electrical network will have two terminals, and itself can participate in a series or parallel topology. Whether a two-terminal "object" is an electrical component (e.g. a resistor) or an electrical network (e.g. resistors in series) is a matter of perspective. This article will use "component" to refer to a two-terminal "object" that participates in the series/parallel networks. Components connected in series are connected along a single "electrical path", and each component has the same electric current through it, equal to the current through the network. The voltage across the network is equal to the sum of the voltages across each component. Components connected in parallel are connected along multiple paths, and each component has the same voltage across it, equal to the voltage across the network. The current through the network is equal to the sum of the currents through each component. The two preceding statements are equivalent, except for exchanging the role of voltage and current. A circuit composed solely of components connected in series is known as a series circuit; likewise, one connected completely in parallel is known as a parallel circuit. Many circuits can be analyzed as a combination of series and parallel circuits, along with other configurations.', 'Wikipedia: Series and parallel circuits', 'https://en.wikipedia.org/w/index.php?title=Series_and_parallel_circuits&oldid=1371301706', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'Two-terminal components and electrical networks can be connected in series or parallel. The resulting electrical network will have two terminals, and itself can participate in a series or parallel topology. Whether a two-terminal "object" is an electrical component (e.g. a resistor) or an electrical network (e.g. resistors in series) is a matter of perspective. This article will use "component" to refer to a two-terminal "object" that participates in the series/parallel networks. Components connected in series are connected along a single "electrical path", and each component has the same electric current through it, equal to the current through the network. The voltage across the network is equal to the sum of the voltages across each component. Components connected in parallel are connected along multiple paths, and each component has the same voltage across it, equal to the voltage across the network. The current through the network is equal to the sum of the currents through each component. The two preceding statements are equivalent, except for exchanging the role of voltage and current. A circuit composed solely of components connected in series is known as a series circuit; likewise, one connected completely in parallel is known as a parallel circuit. Many circuits can be analyzed as a combination of series and parallel circuits, along with other configurations.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Series and parallel circuits', 'In a series circuit, the current that flows through each of the components is the same, and the voltage across the circuit is the sum of the individual voltage drops across each component. In a parallel circuit, the voltage across each of the components is the same, and the total current is the sum of the currents flowing through each component. Consider a very simple circuit consisting of four light bulbs and a 12-volt electric battery. If a wire joins the battery to one bulb, to the next bulb, to the next bulb, to the next bulb, then back to the battery in one continuous loop, the bulbs are said to be in series. If each bulb is wired to the battery in a separate loop, the bulbs are said to be in parallel. If the four light bulbs are connected in series, the same current flows through all of them and the voltage drop is 3 volts across each bulb, which may not be sufficient to make them glow. If the light bulbs are connected in parallel, the currents through the light bulbs combine to form the current in the battery, while the voltage drop is 12 volts across each bulb and they all glow.', 'Wikipedia: Series and parallel circuits', 'https://en.wikipedia.org/w/index.php?title=Series_and_parallel_circuits&oldid=1371301706', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'In a series circuit, the current that flows through each of the components is the same, and the voltage across the circuit is the sum of the individual voltage drops across each component. In a parallel circuit, the voltage across each of the components is the same, and the total current is the sum of the currents flowing through each component. Consider a very simple circuit consisting of four light bulbs and a 12-volt electric battery. If a wire joins the battery to one bulb, to the next bulb, to the next bulb, to the next bulb, then back to the battery in one continuous loop, the bulbs are said to be in series. If each bulb is wired to the battery in a separate loop, the bulbs are said to be in parallel. If the four light bulbs are connected in series, the same current flows through all of them and the voltage drop is 3 volts across each bulb, which may not be sufficient to make them glow. If the light bulbs are connected in parallel, the currents through the light bulbs combine to form the current in the battery, while the voltage drop is 12 volts across each bulb and they all glow.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Series and parallel circuits', 'In a series circuit, every device must function for the circuit to be complete. If one bulb burns out in a series circuit, the entire circuit is broken. In parallel circuits, each light bulb has its own circuit, so all but one light could be burned out, and the last one will still function.', 'Wikipedia: Series and parallel circuits', 'https://en.wikipedia.org/w/index.php?title=Series_and_parallel_circuits&oldid=1371301706', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'In a series circuit, every device must function for the circuit to be complete. If one bulb burns out in a series circuit, the entire circuit is broken. In parallel circuits, each light bulb has its own circuit, so all but one light could be burned out, and the last one will still function.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electricity-magnetism', 'Series and parallel circuits: Series circuits', 'Series circuits are sometimes referred to as current-coupled. The current in a series circuit goes through every component in the circuit. Therefore, all of the components in a series connection carry the same current. A series circuit has only one path through which its current can flow. Opening or breaking a series circuit at any point causes the entire circuit to "open" or stop operating. For example, if even one of the light bulbs in an older-style string of Christmas tree lights burns out or is removed, the entire string becomes inoperable until the faulty bulb is replaced.', 'Wikipedia: Series and parallel circuits', 'https://en.wikipedia.org/w/index.php?title=Series_and_parallel_circuits&oldid=1371301706', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electricity-magnetism' and body = 'Series circuits are sometimes referred to as current-coupled. The current in a series circuit goes through every component in the circuit. Therefore, all of the components in a series connection carry the same current. A series circuit has only one path through which its current can flow. Opening or breaking a series circuit at any point causes the entire circuit to "open" or stop operating. For example, if even one of the light bulbs in an older-style string of Christmas tree lights burns out or is removed, the entire string becomes inoperable until the faulty bulb is replaced.');
